import { MeshBasicNodeMaterial, MeshPhysicalNodeMaterial } from 'three/webgpu';
import {
  uv,
  vec2,
  vec3,
  float,
  mix,
  smoothstep,
  sin,
  dot,
  fract,
  positionLocal,
  normalView,
  cameraPosition,
  positionWorld,
  normalize as tslNormalize,
  clamp,
  pow,
  texture,
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const {
    Group,
    Mesh,
    CylinderGeometry,
    TorusKnotGeometry,
    TorusGeometry,
    PlaneGeometry,
    CircleGeometry,
    Color,
    DirectionalLight,
    DoubleSide,
  } = ctx.THREE;

  const root = new Group();
  root.name = 'pedestal-material-study';

  const colors =
    config.colors ??
    config.intent?.visualSpec?.colors ?? {
      background: '#0b0b10',
      surface: '#14141a',
      ink: '#16161d',
      paper: '#e8ecf2',
      accent: '#ff2a38',
      gradientStops: [
        { at: 0, hex: '#0b0b10' },
        { at: 0.7, hex: '#101017' },
        { at: 1, hex: '#16161d' },
      ],
    };

  const items =
    config.textContent ?? config.intent?.visualSpec?.textContent ?? [
      { text: 'Material study 03', role: 'headline', typography: { fontSize: 68 } },
      { text: 'GRADE 5 TITANIUM / BRUSHED AT 1200 GRIT', role: 'caption', typography: { fontSize: 18 } },
    ];

  const disposables = [];
  const primitiveHandles = [];
  const timelines = [];

  const toVec3 = (hex) => {
    const c = new Color(hex);
    return vec3(c.r, c.g, c.b);
  };

  // ---------------------------------------------------------------
  // BACKDROP — 7x6 plane at z=-3 carrying the vertical gradient
  // ---------------------------------------------------------------
  const stops = colors.gradientStops ?? [
    { at: 0, hex: colors.background },
    { at: 0.7, hex: colors.surface ?? '#101017' },
    { at: 1, hex: colors.ink },
  ];
  const c0 = toVec3(stops[0].hex);
  const c1 = toVec3(stops[1] ? stops[1].hex : stops[0].hex);
  const c2 = toVec3(stops[stops.length - 1].hex);

  const t = uv().y;
  const stageColor = mix(
    mix(c0, c1, smoothstep(float(0.0), float(stops[1] ? stops[1].at : 0.7), t)),
    c2,
    smoothstep(float(stops[1] ? stops[1].at : 0.7), float(1.0), t)
  );

  const backdropGeo = new PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial();
  backdropMat.colorNode = stageColor;
  backdropMat.side = DoubleSide;
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -3);
  root.add(backdrop);
  disposables.push(() => backdropGeo.dispose(), () => backdropMat.dispose());

  // ---------------------------------------------------------------
  // CINEMATIC FLOOR — grounding plane beneath the pedestal
  // ---------------------------------------------------------------
  const floorGeo = new PlaneGeometry(8, 5, 1, 1);
  const floorMat = new MeshPhysicalNodeMaterial();
  const floorBase = toVec3(colors.surface ?? '#14141a');
  const floorEdge = toVec3(colors.background ?? '#0b0b10');
  const floorDist = positionLocal.x.mul(positionLocal.x).add(positionLocal.y.mul(positionLocal.y)).sqrt();
  const floorMixT = smoothstep(float(0.5), float(3.2), floorDist);
  floorMat.colorNode = mix(floorBase, floorEdge, floorMixT);
  floorMat.roughness = 0.55;
  floorMat.metalness = 0.2;
  floorMat.clearcoat = 0.08;
  const floor = new Mesh(floorGeo, floorMat);
  floor.rotation.x = -Math.PI / 2;
  floor.position.set(0, -0.86, 0.4);
  root.add(floor);
  disposables.push(() => floorGeo.dispose(), () => floorMat.dispose());

  // ---------------------------------------------------------------
  // PEDESTAL — cylinder radius 1.1, height 0.5, top face at y=-0.35
  // ---------------------------------------------------------------
  const pedestalGeo = new CylinderGeometry(1.1, 1.1, 0.5, 64);
  const pedestalMat = new MeshPhysicalNodeMaterial();
  const pedestalColor = new Color(colors.surface ?? '#14141a');
  pedestalColor.multiplyScalar(1.4); // lift off pure-black so form reads
  pedestalMat.color = pedestalColor;
  pedestalMat.roughness = 0.65;
  pedestalMat.metalness = 0.4;
  pedestalMat.clearcoat = 0.12;
  pedestalMat.clearcoatRoughness = 0.4;

  // subtle fresnel lift so the cylinder wall doesn't go flat/featureless-black
  const pViewDir = tslNormalize(cameraPosition.sub(positionWorld));
  const pFresnel = pow(clamp(float(1.0).sub(dot(normalView, pViewDir)), 0.0, 1.0), 2.2);
  const pedestalTint = toVec3(colors.paper ?? '#e8ecf2');
  pedestalMat.colorNode = vec3(pedestalColor.r, pedestalColor.g, pedestalColor.b).add(
    pedestalTint.mul(pFresnel).mul(0.12)
  );

  const pedestal = new Mesh(pedestalGeo, pedestalMat);
  pedestal.position.set(0, -0.6, 0);
  root.add(pedestal);
  disposables.push(() => pedestalGeo.dispose(), () => pedestalMat.dispose());

  // chamfered top edge — thin ring catching key light
  const chamferGeo = new TorusGeometry(1.09, 0.03, 16, 64);
  const chamferMat = new MeshPhysicalNodeMaterial();
  chamferMat.color = new Color(colors.paper ?? '#e8ecf2');
  chamferMat.roughness = 0.32;
  chamferMat.metalness = 0.55;
  chamferMat.clearcoat = 0.2;
  const chamfer = new Mesh(chamferGeo, chamferMat);
  chamfer.rotation.x = Math.PI / 2;
  chamfer.position.set(0, -0.35, 0);
  root.add(chamfer);
  disposables.push(() => chamferGeo.dispose(), () => chamferMat.dispose());

  // ---------------------------------------------------------------
  // CONTACT SHADOW — radial gradient plane at y=-0.36
  // ---------------------------------------------------------------
  const shadowGeo = new CircleGeometry(1.5, 64);
  const shadowMat = new MeshBasicNodeMaterial();
  shadowMat.transparent = true;
  shadowMat.depthWrite = false;
  const sDist = positionLocal.x.mul(positionLocal.x).add(positionLocal.y.mul(positionLocal.y)).sqrt();
  const shadowOpacity = float(0.6).mul(float(1.0).sub(smoothstep(float(1.1), float(1.5), sDist)));
  shadowMat.colorNode = vec3(0.0, 0.0, 0.0);
  shadowMat.opacityNode = shadowOpacity;
  const shadow = new Mesh(shadowGeo, shadowMat);
  shadow.rotation.x = -Math.PI / 2;
  shadow.position.set(0, -0.36, 0);
  shadow.renderOrder = 1;
  root.add(shadow);
  disposables.push(() => shadowGeo.dispose(), () => shadowMat.dispose());

  // ---------------------------------------------------------------
  // TORUS KNOT — brushed metal PBR hero subject
  // ---------------------------------------------------------------
  const hash = (uvNode) => fract(sin(dot(uvNode, vec2(12.9898, 78.233))).mul(43758.5453));

  const knotGeo = new TorusKnotGeometry(0.7, 0.22, 220, 36);
  const knotMat = new MeshPhysicalNodeMaterial();
  const knotColor = new Color(0x8f9298); // titanium mid-gray, not white plaster
  knotMat.color = knotColor;
  knotMat.roughness = 0.55;
  knotMat.metalness = 0.55;
  knotMat.clearcoat = 0.22;
  knotMat.clearcoatRoughness = 0.35;
  if ('anisotropy' in knotMat) {
    knotMat.anisotropy = 0.9;
    knotMat.anisotropyRotation = Math.PI / 2;
  }

  // imperfection pass: 2% roughness value jitter so highlights break up
  const jitterUv = uv().mul(60.0);
  const jitter = hash(jitterUv).sub(0.5).mul(0.02);
  let baseRoughnessNode = float(0.55).add(jitter);
  knotMat.roughnessNode = baseRoughnessNode;

  // scratch-noise micro normal perturbation, kept small + in view space
  const scratchUv = uv().mul(320.0);
  const scratch = hash(scratchUv).sub(0.5);
  const scratchB = hash(scratchUv.add(vec2(13.7, 91.3))).sub(0.5);
  const scratchPerturb = vec3(scratch, scratchB, 0.0).mul(0.06);
  knotMat.normalNode = tslNormalize(normalView.add(scratchPerturb));

  // fake environment response so metal doesn't render flat/black without IBL:
  // fresnel-driven lift toward the paper tone, capped low to avoid blowout
  const kViewDir = tslNormalize(cameraPosition.sub(positionWorld));
  const kFresnel = pow(clamp(float(1.0).sub(dot(normalView, kViewDir)), 0.0, 1.0), 3.0);
  const paperTint = toVec3(colors.paper ?? '#e8ecf2');
  knotMat.emissiveNode = paperTint.mul(kFresnel).mul(0.18);

  const knot = new Mesh(knotGeo, knotMat);
  knot.position.set(0, 0.4, 0);
  root.add(knot);
  disposables.push(() => knotGeo.dispose(), () => knotMat.dispose());

  // roughness map (brushed-metal texture) — multiplies, centered ~0.9, swap-proof
  if (config.imageUrl) {
    ctx.textureLoader
      .loadTexture(config.imageUrl)
      .then((tex) => {
        const mapSample = texture(tex).r;
        const centered = mapSample.mul(0.2).add(0.9);
        knotMat.roughnessNode = float(0.55).mul(centered).add(jitter);
        knotMat.needsUpdate = true;
      })
      .catch(() => {});
  }

  // ---------------------------------------------------------------
  // LIGHTS — scene provides ambient 0.6 + key 1.2; add rim/fill node-locally
  // ---------------------------------------------------------------
  const rim = new DirectionalLight(new Color(colors.accent ?? '#ff2a38'), 0.7);
  rim.position.set(-2.2, 1.6, -1.6);
  root.add(rim);

  const fill = new DirectionalLight(new Color(0xf4f4f8), 0.35);
  fill.position.set(2.4, 1.0, 2.6);
  root.add(fill);

  disposables.push(
    () => rim.dispose && rim.dispose(),
    () => fill.dispose && fill.dispose()
  );

  // ---------------------------------------------------------------
  // TEXT
  // ---------------------------------------------------------------
  const headlineItem = items.find((i) => i.role === 'headline') ?? items[0];
  const captionItem = items.find((i) => i.role === 'caption') ?? items[1];

  let headline = null;
  let caption = null;

  if (headlineItem) {
    headline = ctx.fontAtlas.createText(headlineItem.text, {
      fontSize: headlineItem.typography?.fontSize ?? 68,
      color: colors.paper ?? '#e8ecf2',
      align: 'center',
    });
    headline.position.set(0, -1.2, 0.01);
    root.add(headline);
  }

  if (captionItem) {
    caption = ctx.fontAtlas.createText(captionItem.text, {
      fontSize: captionItem.typography?.fontSize ?? 18,
      color: colors.paper ?? '#e8ecf2',
      align: 'center',
      letterSpacingPx: 1.4,
    });
    caption.position.set(0, -1.6, 0.01);
    root.add(caption);
  }

  // ---------------------------------------------------------------
  // ENTRANCE MOTION — weighted-settle
  // ---------------------------------------------------------------
  knot.scale.setScalar(0.001);
  root.position.y = -0.3;
  const settleTl = gsap.timeline();
  settleTl.to(root.position, { y: 0, duration: 0.7, ease: 'power3.out' }, 0);
  settleTl.to(
    knot.scale,
    {
      x: 1.04,
      y: 1.04,
      z: 1.04,
      duration: 0.5,
      ease: 'power2.out',
      onComplete: () => {
        gsap.to(knot.scale, { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' });
      },
    },
    0.05
  );
  timelines.push(settleTl);

  // ---------------------------------------------------------------
  // CINEMATIC PRIMITIVES
  // ---------------------------------------------------------------
  const prims = config.cinematicPrimitives ?? [];
  for (const primitive of prims) {
    const applyFn = ctx.primitives[primitive.name];
    if (typeof applyFn === 'function') {
      const target = knot;
      const handle = applyFn(target, primitive.params ?? {});
      if (handle) primitiveHandles.push(handle);
    }
  }

  // ---------------------------------------------------------------
  // CLEANUP
  // ---------------------------------------------------------------
  root.userData.cleanup = () => {
    for (const tl of timelines) {
      tl.kill();
    }
    for (const handle of primitiveHandles) {
      handle.timeline?.kill?.();
      handle.cleanup?.();
    }
    for (const dispose of disposables) {
      try {
        dispose();
      } catch (e) {
        /* noop */
      }
    }
    headline?.userData?.dispose?.();
    caption?.userData?.dispose?.();
    root.traverse((child) => {
      if (child.isMesh) {
        child.geometry?.dispose?.();
        if (Array.isArray(child.material)) {
          child.material.forEach((m) => m.dispose?.());
        } else {
          child.material?.dispose?.();
        }
      }
    });
  };

  root.userData.handlers = {};

  return root;
}
